sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	// Get the parent Incident
    if (!current.parent || current.parent.getTableName() != 'incident')
        return;

    var incidentGR = current.parent.getRefRecord();
    if (!incidentGR.isValidRecord())
        return;

    // Check for any open RITMs under the incident
    var ritm = new GlideRecord('sc_req_item');
    ritm.addQuery('parent', incidentGR.sys_id);
    ritm.addQuery('state', '!=', 3); // Closed Complete
    ritm.query();

    var openRitmExists = ritm.hasNext();

    // Check for any open Catalog Tasks under the incident
    var task = new GlideRecord('sc_task');
    task.addQuery('parent', incidentGR.sys_id);
    task.addQuery('state', '!=', 3); // Closed Complete
    task.query();

    var openTaskExists = task.hasNext();

    // If both are complete, close the incident
    if (!openRitmExists && !openTaskExists) {
        incidentGR.state = 6; // Resolved/Closed (use appropriate value)
        incidentGR.close_code = "Solved (Permanently)";
        incidentGR.close_notes = "All associated RITMs and Catalog Tasks have been completed.";
        incidentGR.update();
    }

})(current, previous);
